from io import StringIO
from types import SimpleNamespace
from unittest import mock

class RecordingFile(object):
    def __init__(self):
        self.data = ""
        self.closed = False

    def write(self, data):
        self.data += data

    def close(self):
        self.closed = True

class FakeConnection(object):
    def __init__(self):
        self.options = None
        self._socket_path = None

    def set_options(self, var_options):
        self.options = var_options

class FakeServer(object):
    def __init__(self):
        self.registered = None

    def register(self, connection):
        self.registered = connection

class FakeSocket(object):
    def __init__(self):
        self.bound_path = None
        self.backlog = None

    def bind(self, path):
        self.bound_path = path

    def listen(self, backlog):
        self.backlog = backlog

play_context = SimpleNamespace(
    private_key_file="keys/id_rsa",
    connection="network_cli",
)
output = RecordingFile()
process = ConnectionProcess(
    output,
    play_context,
    "/tmp/control.sock",
    "/original",
    task_uuid="task-123",
    ansible_playbook_pid=456,
)
process.srv = FakeServer()
fake_connection = FakeConnection()
fake_socket = FakeSocket()
captured_loader_call = {}

def fake_get(connection_name, context, path, **kwargs):
    captured_loader_call["args"] = (connection_name, context, path)
    captured_loader_call["kwargs"] = kwargs
    print("loader initialized")
    return fake_connection

with mock.patch.object(connection_loader, "get", side_effect=fake_get), \
        mock.patch.object(socket, "socket", return_value=fake_socket) as socket_factory, \
        mock.patch.object(sys, "stdout", StringIO()):
    process.start({"ansible_host": "router.example.com"})

assert json.loads(output.data) == {
    "messages": [
        ["vvvv", "control socket path is /tmp/control.sock"],
        ["vvvv", "loader initialized"],
        ["vvvv", "local domain socket listeners started successfully"],
    ]
}
assert output.closed is True
assert play_context.private_key_file == "/original/keys/id_rsa"
assert fake_connection.options == {"ansible_host": "router.example.com"}
assert fake_connection._socket_path == "/tmp/control.sock"
assert process.srv.registered is fake_connection
assert fake_socket.bound_path == "/tmp/control.sock"
assert fake_socket.backlog == 1
assert captured_loader_call == {
    "args": ("network_cli", play_context, "/dev/null"),
    "kwargs": {
        "task_uuid": "task-123",
        "ansible_playbook_pid": 456,
    },
}
socket_factory.assert_called_once_with(socket.AF_UNIX, socket.SOCK_STREAM)
